package in.guvi.fraud.web;
import in.guvi.fraud.dao.TransactionDao;import in.guvi.fraud.model.Transaction;import in.guvi.fraud.service.DetectionService;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.math.BigDecimal;
@WebServlet("/user") public class UserServlet extends RoleServlet{
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException,ServletException{if(!require(q,p,"user"))return;try{q.setAttribute("tx",((TransactionDao)getServletContext().getAttribute("dao")).list(100,false));q.getRequestDispatcher("/user.jsp").forward(q,p);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException,ServletException{if(!require(q,p,"user"))return;try{Transaction t=new Transaction();t.customerId=clean(q.getParameter("customerId"));t.amount=new BigDecimal(clean(q.getParameter("amount")));t.paymentMethod=clean(q.getParameter("paymentMethod"));t.location=clean(q.getParameter("location"));if(t.customerId.isBlank()||t.customerId.length()>80||t.amount.signum()<=0||t.paymentMethod.isBlank()||t.location.isBlank()||t.location.length()>100)throw new IllegalArgumentException("Enter valid values in every field.");((DetectionService)getServletContext().getAttribute("detector")).evaluate(t);((TransactionDao)getServletContext().getAttribute("dao")).save(t);p.sendRedirect(q.getContextPath()+"/user?saved=1");}catch(IllegalArgumentException e){q.setAttribute("error",e.getMessage());doGet(q,p);}catch(Exception e){throw new ServletException(e);}}
 private String clean(String s){return s==null?"":s.trim();}
}
